29	describe("extractIndices", () => {
30	  it("prefers pointIndex and falls back to pointNumber", () => {
31	    const points = [
32	      makePoint({
33	        pointIndex: 2,
34	        pointNumber: 99,
35	        data: { type: "scatter" },
36	      }),
