def _to_numeric_coord(value: Any) -> Any:
    """Convert a datetime/ISO-string coordinate to a numeric value.

    Naive datetimes are treated as UTC so that a naive datetime, a UTC-aware
    datetime, and a UTC ISO-8601 string all produce the same numeric value,
    independent of the system timezone.

    Non-datetime values are returned unchanged.
    """
    import datetime

    dt: Optional[datetime.datetime] = None

    if isinstance(value, str):
        try:
            dt = datetime.datetime.fromisoformat(value.replace("Z", "+00:00"))
        except (ValueError, AttributeError):
            return value
    elif isinstance(value, datetime.datetime):
        dt = value
    elif isinstance(value, datetime.date):
        dt = datetime.datetime(value.year, value.month, value.day)

    if dt is None:
        return value

    # Treat naive datetimes as UTC so the result is timezone-independent.
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)

    return dt.timestamp()


def _coerce_numeric(value: Any) -> Optional[float]:
    """Coerce a coordinate to a float, converting datetimes via UTC.

    Returns None when the value cannot be represented numerically (e.g. a
    categorical string label).
    """
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    converted = _to_numeric_coord(value)
    if isinstance(converted, bool):
        return None
    if isinstance(converted, (int, float)):
        return float(converted)
    return None


def _bar_value_in_selection_range(
    *,
    trace: Any,
    point_idx: int,
    point_value: Any,
    selection_min: Any,
    selection_max: Any,
) -> bool:
    """Return whether a bar's value extent overlaps the selection range.

    A bar spans from its ``base`` (default 0) to ``base + value``. The bar is
    considered selected when that extent overlaps the value-axis selection
    range. Returns ``False`` (never raises) when the point value or the trace
    base contain non-numeric values.
    """
    if isinstance(point_value, bool) or not isinstance(
        point_value, (int, float)
    ):
        return False

    base = getattr(trace, "base", None)
    base_value = 0.0
    if base is not None:
        if isinstance(base, bool):
            return False
        if isinstance(base, (int, float)):
            base_value = float(base)
        else:
            resolved = _get_indexed_value(base, point_idx)
            if resolved is None:
                base_value = 0.0
            elif isinstance(resolved, bool) or not isinstance(
                resolved, (int, float)
            ):
                return False
            else:
                base_value = float(resolved)

    top = base_value + float(point_value)
    bar_lo, bar_hi = min(base_value, top), max(base_value, top)

    sel_lo = _coerce_numeric(selection_min)
    sel_hi = _coerce_numeric(selection_max)
    if sel_lo is None or sel_hi is None:
        # Cannot compare against a non-numeric value axis: don't exclude.
        return True
    if sel_lo > sel_hi:
        sel_lo, sel_hi = sel_hi, sel_lo

    return not (bar_hi < sel_lo or bar_lo > sel_hi)


def _point_in_polygon(
    x: float, y: float, poly_x: list[float], poly_y: list[float]
) -> bool:
    """Ray-casting point-in-polygon test for numeric coordinates."""
    n = len(poly_x)
    inside = False
    j = n - 1
    for i in range(n):
        xi, yi = poly_x[i], poly_y[i]
        xj, yj = poly_x[j], poly_y[j]
        if ((yi > y) != (yj > y)) and (
            x < (xj - xi) * (y - yi) / (yj - yi) + xi
        ):
            inside = not inside
        j = i
    return inside


def _category_positions(values: Any) -> dict[Any, int]:
    """Map category labels to integer positions (repeated labels share one)."""
    positions: dict[Any, int] = {}
    for value in values:
        key = value.item() if hasattr(value, "item") else value
        if key not in positions:
            positions[key] = len(positions)
    return positions


def _scatter_axis_fields(figure: go.Figure) -> tuple[str, str]:
    """Return the (x, y) field names derived from single axis titles."""
    x_axes: list[go.layout.XAxis] = []
    figure.for_each_xaxis(x_axes.append)
    x_axis = x_axes[0] if len(x_axes) == 1 else None

    y_axes: list[go.layout.YAxis] = []
    figure.for_each_yaxis(y_axes.append)
    y_axis = y_axes[0] if len(y_axes) == 1 else None

    x_field = x_axis.title.text if (x_axis and x_axis.title.text) else "x"
    y_field = y_axis.title.text if (y_axis and y_axis.title.text) else "y"
    return x_field, y_field


def _axis_mask_numpy(arr: Any, lo: Any, hi: Any) -> Any:
    """Compute a boolean membership mask for a numpy axis array.

    An unbounded range (``lo``/``hi`` is None) matches everything. Orderable
    axes are compared directly; categorical axes map labels to integer
    positions (repeated labels share a position) before range comparison.
    """
    import numpy as np

    n = len(arr)
    if lo is None or hi is None:
        return np.ones(n, dtype=bool)

    if _is_orderable_axis(arr, lo):
        lo_p = _parse_datetime_bound(lo)
        hi_p = _parse_datetime_bound(hi)
        return (arr >= lo_p) & (arr <= hi_p)

    positions = _category_positions(arr.tolist())
    pos = np.asarray(
        [positions[v] for v in arr.tolist()], dtype=float
    )
    lo_n, hi_n = float(lo), float(hi)
    return (hi_n > pos - 0.5) & (lo_n < pos + 0.5)


def _axis_mask_fallback(data: Any, lo: Any, hi: Any) -> list[bool]:
    """Pure-Python equivalent of :func:`_axis_mask_numpy`."""
    data_list = list(data)
    n = len(data_list)
    if lo is None or hi is None:
        return [True] * n

    orderable = (
        _is_orderable_value(lo) and n > 0 and _is_orderable_value(data_list[0])
    )
    if orderable:
        lo_p = _parse_datetime_bound(lo)
        hi_p = _parse_datetime_bound(hi)
        mask: list[bool] = []
        for value in data_list:
            if _is_orderable_value(value):
                try:
                    mask.append(bool(lo_p <= value <= hi_p))
                except TypeError:
                    mask.append(False)
            else:
                mask.append(False)
        return mask

    positions = _category_positions(data_list)
    lo_n, hi_n = float(lo), float(hi)
    return [
        not (hi_n <= positions[value] - 0.5 or lo_n >= positions[value] + 0.5)
        for value in data_list
    ]


